)
insert into public.syllabus_topics (edition_id,block_name,discipline,topic_order,topic_text)
select edition.id, data.block_name, data.discipline, 1, data.topic_text from edition cross join (values
('Conhecimentos Gerais','Língua Portuguesa','Compreensão e interpretação textual; coesão e coerência; correção gramatical; substituição vocabular — questões 1 a 7 do caderno.'),
('Conhecimentos Gerais','Matemática Financeira','Juros simples e compostos, desconto racional simples, valor presente e futuro — questões 8 a 10 do caderno.'),
('Conhecimentos Gerais','Raciocínio Lógico','Lógica proposicional, argumentos válidos, sequências numéricas — questões 11 a 15 do caderno.'),
('Conhecimentos Gerais','Informática','Edição de documentos acessíveis, ferramentas de busca, armazenamento em nuvem, LGPD (Lei nº 13.709/2018) — questões 16 a 19 do caderno.'),
('Conhecimentos Gerais','Realidade do Acre','História, geografia, cultura e economia do estado do Acre — questões 20 a 30 do caderno.'),
('Conhecimentos Específicos','Administração Pública','Orçamento participativo, indicadores de desempenho, OSCIP, descentralização, Lei de Acesso à Informação, improbidade administrativa, processo administrativo — questões 31 a 44 do caderno.'),
('Conhecimentos Específicos','Direito Tributário','Substituição tributária, IPI, ICMS (diferencial de alíquota, monofásico) — questões 45 a 48 do caderno.'),
('Conhecimentos Específicos','Direito Constitucional','Ações constitucionais, intervenção federal, Poder Judiciário, ADI, direitos indígenas e quilombolas, Constituição do Estado do Acre — questões 49 a 54 do caderno.'),
('Conhecimentos Específicos','Orçamento Público','LDO, PPA, LOA, sistema de controle interno e externo — questões 55 a 60 do caderno.')
) as data(block_name,discipline,topic_text)
on conflict (edition_id,discipline,topic_order) do update set topic_text=excluded.topic_text, content_status='current';

with sources as (
  select
    (select id from public.content_sources where url='https://cdn.cebraspe.org.br/concursos/sefaz_ac_23/arquivos/ED_1_SEFAZ_AC_23_ABERTURA.PDF') as prova_id,
    (select id from public.content_sources where url='https://cdn.cebraspe.org.br/concursos/sefaz_ac_23/arquivos/GAB_DEFINITIVO_946_SEFAZ_AC_CG2_01.PDF') as gab_gerais_id,
    (select id from public.content_sources where url='https://cdn.cebraspe.org.br/concursos/sefaz_ac_23/arquivos/GAB_DEFINITIVO_946_SEFAZ_AC_003_01.PDF') as gab_especificos_id
),
topics as (
  select t.discipline, t.id as topic_id
